// BillingServiceServer is the server API for BillingService service.
// All implementations must embed UnimplementedBillingServiceServer
// for forward compatibility.
//
// BillingService serves invoices. The tenant comes from gRPC metadata, never from a request body.
type BillingServiceServer interface {
	GetInvoice(context.Context, *GetInvoiceRequest) (*GetInvoiceResponse, error)
	ListInvoices(context.Context, *ListInvoicesRequest) (*ListInvoicesResponse, error)
	// GetInvoicePdfUrl returns a presigned link to the invoice PDF (valid for 5 minutes).
	GetInvoicePdfUrl(context.Context, *GetInvoicePdfUrlRequest) (*GetInvoicePdfUrlResponse, error)
	// GetRevenueReport sums the tenant's invoices by period, payment provider, customer country and currency. Currencies are never added together.
	GetRevenueReport(context.Context, *GetRevenueReportRequest) (*GetRevenueReportResponse, error)
	// GetDunningReport lists the invoices whose payment has not gone through: declined, unknown or given up.
	GetDunningReport(context.Context, *GetDunningReportRequest) (*GetDunningReportResponse, error)
	GetCreditNote(context.Context, *GetCreditNoteRequest) (*GetCreditNoteResponse, error)
	ListCreditNotes(context.Context, *ListCreditNotesRequest) (*ListCreditNotesResponse, error)
	// GetEInvoice returns one e-document (the legal copy of an invoice or credit note) and its state.
	GetEInvoice(context.Context, *GetEInvoiceRequest) (*GetEInvoiceResponse, error)
	// ListEInvoices lists the tenant's e-documents, newest first.
	ListEInvoices(context.Context, *ListEInvoicesRequest) (*ListEInvoicesResponse, error)
	// GetEInvoiceFileUrl returns a presigned link (5 minutes) to the document's UBL XML or PDF.
	GetEInvoiceFileUrl(context.Context, *GetEInvoiceFileUrlRequest) (*GetEInvoiceFileUrlResponse, error)
	// CreateInvoiceLink makes an unguessable link to a finalized invoice, for the tenant to send to its customer. The token is returned once.
	CreateInvoiceLink(context.Context, *CreateInvoiceLinkRequest) (*CreateInvoiceLinkResponse, error)
	// RevokeInvoiceLinks makes every link to an invoice stop working.
	RevokeInvoiceLinks(context.Context, *RevokeInvoiceLinksRequest) (*RevokeInvoiceLinksResponse, error)
	// CreatePaymentLink makes a payment link (phase 34): for an open invoice, or ad hoc for a fixed amount. The token is returned once. Idempotent per idempotency_key.
	CreatePaymentLink(context.Context, *CreatePaymentLinkRequest) (*CreatePaymentLinkResponse, error)
	GetPaymentLink(context.Context, *GetPaymentLinkRequest) (*GetPaymentLinkResponse, error)
	ListPaymentLinks(context.Context, *ListPaymentLinksRequest) (*ListPaymentLinksResponse, error)
	// RevokePaymentLink stops a link (and the links it handed out) from working. An ad-hoc invoice nobody has paid is voided.
	RevokePaymentLink(context.Context, *RevokePaymentLinkRequest) (*RevokePaymentLinkResponse, error)
	// CreatePortalLink makes the link to a customer's payment-history page. The token is returned once.
	CreatePortalLink(context.Context, *CreatePortalLinkRequest) (*CreatePortalLinkResponse, error)
	RevokePortalLinks(context.Context, *RevokePortalLinksRequest) (*RevokePortalLinksResponse, error)
	// SettleInvoicePayment is called by payments-worker when a provider confirmed a payment made on a hosted page. It moves the invoice's saga to paid.
	SettleInvoicePayment(context.Context, *SettleInvoicePaymentRequest) (*SettleInvoicePaymentResponse, error)
	// GetDunningSettings returns the tenant's retry delays; defaults_in_use is true when none were set.
	GetDunningSettings(context.Context, *GetDunningSettingsRequest) (*GetDunningSettingsResponse, error)
	// SetDunningSettings replaces the delays between a declined charge and each retry (0 to 6 entries; none means a declined charge is given up at once).
	SetDunningSettings(context.Context, *SetDunningSettingsRequest) (*SetDunningSettingsResponse, error)
	// ListCreditPacks lists the credit packs the tenant sells.
	ListCreditPacks(context.Context, *ListCreditPacksRequest) (*ListCreditPacksResponse, error)
	// CreateCreditPack adds a pack: a number of credits for a price in one currency.
	CreateCreditPack(context.Context, *CreateCreditPackRequest) (*CreateCreditPackResponse, error)
	// SetCreditPackActive withdraws a pack from sale or puts it back. Credits already sold are not touched.
	SetCreditPackActive(context.Context, *SetCreditPackActiveRequest) (*SetCreditPackActiveResponse, error)
	// GetCreditBalance returns what a customer can spend now and when some of it runs out.
	GetCreditBalance(context.Context, *GetCreditBalanceRequest) (*GetCreditBalanceResponse, error)
	// GrantCredits adds credits to a customer (a promotion, a goodwill gesture, a manual sale). With the same idempotency key a repeat does nothing.
	GrantCredits(context.Context, *GrantCreditsRequest) (*GrantCreditsResponse, error)
	// ConsumeCredits takes credits from a customer, the ones that expire first. FAILED_PRECONDITION (billing.credits.insufficient) when the balance is too small;
	// nothing is taken then. With the same idempotency key a repeat returns the first result.
	ConsumeCredits(context.Context, *ConsumeCreditsRequest) (*ConsumeCreditsResponse, error)
	// ListCreditLedger lists a customer's credit changes, newest first.
	ListCreditLedger(context.Context, *ListCreditLedgerRequest) (*ListCreditLedgerResponse, error)
	// CreateExpense records money the tenant spent (or spends every month or year).
	CreateExpense(context.Context, *CreateExpenseRequest) (*CreateExpenseResponse, error)
	// UpdateExpense replaces the fields of an expense that has not been voided. A recurring expense changes as a whole, all its occurrences.
	UpdateExpense(context.Context, *UpdateExpenseRequest) (*UpdateExpenseResponse, error)
	// VoidExpense takes an expense out of every summary, with a reason. It stays listable (include_voided).
	VoidExpense(context.Context, *VoidExpenseRequest) (*VoidExpenseResponse, error)
	// ListExpenses lists the entries as recorded, newest first; a recurring expense is one entry.
	ListExpenses(context.Context, *ListExpensesRequest) (*ListExpensesResponse, error)
	// GetAccountingSummary adds up income (from paid invoices, tax and refunds) and expenses over a period, one block per currency. Currencies are never converted or added together.
	GetAccountingSummary(context.Context, *GetAccountingSummaryRequest) (*GetAccountingSummaryResponse, error)
	mustEmbedUnimplementedBillingServiceServer()
}

